css:
.loader-stage {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100%;
  width: 100%;
  background-color: #ffffff;
  overflow: hidden;
  user-select: none;
}

.pixar-container {
  --yellow: #feca57;
  --red: #ff6b6b;
  --blue: #48dbfb;
  --depth-y: #e1ad21;
  --depth-r: #ee5253;
  --shadow-clr: rgba(0, 0, 0, 0.08);
  --fs: 4.5em;
  --bounce-ease: cubic-bezier(0.68, -0.6, 0.32, 1.6);

  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
}

.laughing-group {
  display: flex;
  gap: 0.08em;
  font-family: "Arial Rounded MT Bold", "Helvetica Rounded", system-ui,
    sans-serif;
  font-size: var(--fs);
  font-weight: 900;
  perspective: 800px;
}

.toy-letter {
  display: inline-block;
  position: relative;
  color: var(--yellow);
  transform-origin: center bottom;
  filter: drop-shadow(0 0.1em 0.2em var(--shadow-clr));
  animation:
    laugh-bounce 0.6s infinite alternate var(--bounce-ease),
    laugh-wobble 0.3s infinite alternate ease-in-out;
  text-shadow:
    0 0.01em 0 var(--depth-y),
    0 0.02em 0 var(--depth-y),
    0 0.03em 0 var(--depth-y),
    0 0.04em 0 var(--depth-y),
    0 0.05em 0 var(--depth-y),
    0 0.06em 0 var(--depth-y),
    0 0.07em 0.1em rgba(0, 0, 0, 0.2);
}

.toy-letter::after {
  content: "";
  position: absolute;
  top: 10%;
  left: 15%;
  width: 35%;
  height: 20%;
  background: rgba(255, 255, 255, 0.5);
  border-radius: 100%;
  filter: blur(2px);
  pointer-events: none;
}

.toy-letter:nth-child(even) {
  color: var(--red);
  animation-delay: 0.1s;
  text-shadow:
    0 0.01em 0 var(--depth-r),
    0 0.02em 0 var(--depth-r),
    0 0.03em 0 var(--depth-r),
    0 0.04em 0 var(--depth-r),
    0 0.05em 0 var(--depth-r),
    0 0.06em 0 var(--depth-r),
    0 0.07em 0.1em rgba(0, 0, 0, 0.2);
}

.toy-letter:nth-child(1) {
  animation-delay: 0.05s;
}
.toy-letter:nth-child(2) {
  animation-delay: 0.12s;
}
.toy-letter:nth-child(3) {
  animation-delay: 0.08s;
}
.toy-letter:nth-child(4) {
  animation-delay: 0.15s;
}
.toy-letter:nth-child(5) {
  animation-delay: 0.03s;
}
.toy-letter:nth-child(6) {
  animation-delay: 0.1s;
}
.toy-letter:nth-child(7) {
  animation-delay: 0.18s;
}

.ground-shadow {
  width: 12em;
  height: 0.8em;
  background: radial-gradient(
    ellipse at center,
    rgba(0, 0, 0, 0.1) 0%,
    transparent 75%
  );
  border-radius: 50%;
  margin-top: 0.5em;
  animation: shadow-morph 0.6s infinite alternate var(--bounce-ease);
}

@keyframes laugh-bounce {
  0% {
    transform: translateY(0) scale(1.1, 0.85);
  }
  100% {
    transform: translateY(-0.5em) scale(0.95, 1.1) rotate(-5deg);
  }
}

@keyframes laugh-wobble {
  0% {
    transform: rotate(-2deg);
  }
  100% {
    transform: rotate(2deg);
  }
}

@keyframes shadow-morph {
  0% {
    transform: scaleX(1.1);
    opacity: 0.6;
    filter: blur(2px);
  }
  100% {
    transform: scaleX(0.7);
    opacity: 0.2;
    filter: blur(5px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .toy-letter,
  .ground-shadow {
    animation: none !important;
    transform: none !important;
  }
}
